mapper.select:
select * from (SELECT REVEAL.ID id ,REVEAL.REP_ID repId ,REVEAL.REPORT_NAME reportName ,REVEAL.PROD_NAME prodName ,REVEAL.PRODID prodid ,case when REVEAL.START_DATE is null or REVEAL.START_DATE = REVEAL.END_DATE then DATE_FORMAT(REVEAL.END_DATE,'%Y-%m-%d') else concat_ws('', DATE_FORMAT(REVEAL.START_DATE,'%Y-%m-%d'), '--', DATE_FORMAT(REVEAL.END_DATE,'%Y-%m-%d')) end reportDate ,REVEAL.END_DATE endDate ,REVEAL.START_DATE startDate ,REVEAL.SYS_FILENAME sysFilename ,REVEAL.SYS_FILEPATH sysFilepath ,REVEAL.REVEAL_DATE revealDate ,REVEAL.FILEPATH filepath ,REVEAL.FILENAME filename ,REVEAL.CONFIRM_STATUS confirmStatus
,REVEAL.REVEAL_STATUS revealStatus
,REVEAL.STATUS status ,REVEAL.CREATE_USER createUser ,REVEAL.CREATE_DEPT createDept ,REVEAL.CREATE_TIME createTime ,REVEAL.UPDATE_USER updateUser ,REVEAL.UPDATE_TIME updateTime ,DATE_FORMAT(REVEAL.CREATE_TIME,'%Y-%m-%d') createTimeStr ,DATE_FORMAT(REVEAL.CONFIRM_DATE,'%Y-%m-%d') confirmDateStr ,REVEAL.SYS_FILEPATH seqno
,REVEAL.REVEAL_CHANNEL revealChannel ,REVEAL.IS_CONFIRM isConfirm ,REVEAL.IS_REVEAL isReveal
,REVEAL.DETAIL detail ,DATE_FORMAT(REVEAL.TIME,'%Y-%m-%d') uploadTime ,REVEAL.CONFIRM_USER confirmUser ,REVEAL.REPORT_CATEGORY reportCategory ,rfp.NAME reportCategoryName ,DATE_FORMAT(REVEAL.REVEAL_END_DATE,'%Y-%m-%d %H:%i') revealEndDateStr ,REVEAL.ANNEX annex ,REVEAL.ANNEX_PATH annexPath FROM REP_REVEAL REVEAL left join rep_info info on REVEAL.rep_id = info.rep_id left join rep_ftp_path rfp on REVEAL.REPORT_CATEGORY = rfp.ID
left join rep_prod_info pd on REVEAL.PRODID = pd.PROD_ID
where 1=1 and REVEAL.status ='E'
AND if(REVEAL.REVEAL_STATUS=null,'1',REVEAL.REVEAL_STATUS) = #{revealStatus,jdbcType=VARCHAR}
AND REVEAL.PRODID IN
#{item}
AND REVEAL.REPORT_NAME like concat_ws('', '%', #{reportName,jdbcType=VARCHAR}, '%')
AND DATE_FORMAT(REVEAL.CREATE_TIME,'%Y-%m-%d') >= #{valDateBegin,jdbcType=VARCHAR}
AND DATE_FORMAT(REVEAL.CREATE_TIME,'%Y-%m-%d') <= #{valDateEnd,jdbcType=VARCHAR}
AND if(REVEAL.CONFIRM_STATUS=null,'02',REVEAL.CONFIRM_STATUS) = #{confirmStatus,jdbcType=VARCHAR}
AND DATE_FORMAT(REVEAL.CONFIRM_DATE,'%Y-%m-%d') >= #{confirmDateBegin,jdbcType=VARCHAR}
AND DATE_FORMAT(REVEAL.CONFIRM_DATE,'%Y-%m-%d') <= #{confirmDateEnd,jdbcType=VARCHAR}
AND REVEAL.IS_CONFIRM IN
#{item}
and(
REVEAL.REVEAL_CHANNEL like concat_ws('', '%', #{item}, '%')
)
AND DATE_FORMAT(REVEAL.REVEAL_DATE,'%Y-%m-%d') >= #{revealDateBegin,jdbcType=VARCHAR}
AND DATE_FORMAT(REVEAL.REVEAL_DATE,'%Y-%m-%d') <= #{revealDateEnd,jdbcType=VARCHAR}
AND DATE_FORMAT(REVEAL.REVEAL_END_DATE,'%Y-%m-%d') >= #{revealEndDateBegin,jdbcType=VARCHAR}
AND DATE_FORMAT(REVEAL.REVEAL_END_DATE,'%Y-%m-%d') <= #{revealEndDateEnd,jdbcType=VARCHAR}
AND REVEAL.REPORT_CATEGORY IN
#{item}
and pd.RAISE_TYPE = #{raiseType,jdbcType=VARCHAR}
and ( pd.SALETARGET_DECLARE like '%03%' /** 一般个人客户**/ or pd.SALETARGET_DECLARE like '%05%' /** 高资产净值客户**/ or pd.SALETARGET_DECLARE like '%01%' /** 私人银行客户专属**/ )
and pd.SALETARGET_DECLARE like '%02%' /** 机构客户专属**/
and pd.SALETARGET_DECLARE like '%04%' /** 金融同业专属**/
and ( pd.SALETARGET_DECLARE like '%03%' /** 一般个人客户**/ or pd.SALETARGET_DECLARE like '%05%' /** 高资产净值客户**/ or pd.SALETARGET_DECLARE like '%01%' /** 私人银行客户专属**/ ) and pd.SALETARGET_DECLARE like '%02%' /** 机构客户专属**/
and ( pd.SALETARGET_DECLARE like '%03%' /** 一般个人客户**/ or pd.SALETARGET_DECLARE like '%05%' /** 高资产净值客户**/ or pd.SALETARGET_DECLARE like '%01%' /** 私人银行客户专属**/ ) and pd.SALETARGET_DECLARE like '%04%' /** 金融同业专属**/
and pd.SALETARGET_DECLARE like '%02%' /** 机构客户专属**/ and pd.SALETARGET_DECLARE like '%04%' /** 金融同业专属**/
and ( pd.SALETARGET_DECLARE like '%03%' /** 一般个人客户**/ or pd.SALETARGET_DECLARE like '%05%' /** 高资产净值客户**/ or pd.SALETARGET_DECLARE like '%01%' /** 私人银行客户专属**/ ) and pd.SALETARGET_DECLARE like '%04%' /** 金融同业专属**/ and pd.SALETARGET_DECLARE like '%02%' /** 机构客户专属**/
order by REVEAL.CONFIRM_STATUS ASC,
REVEAL.REVEAL_STATUS DESC,
REVEAL.CREATE_TIME DESC) tmp where 1=1

select prd.finprod_id,IFNULL(prd.finprod_abbr,prd.finprod_name) finprod_abbr from fin_product prd 
	where 1=1

	AND prd.FINPROD_TYPE = #{finprodType}


 SELECT 
		concat_ws('', r.PROD_NAME, '_', rfp.NAME) as SYS_FILENAME
 FROM REP_REVEAL r 
 left join  rep_ftp_path  rfp
 ON
     r.REPORT_CATEGORY = rfp.ID
 WHERE r.SYS_FILEPATH=#{sysFilepath, jdbcType=VARCHAR}
 or  r.FILEPATH=#{sysFilepath, jdbcType=VARCHAR}
 or  r.ANNEX_PATH=#{sysFilepath, jdbcType=VARCHAR}

mapper.update:
      update REP_REVEAL
      set 
      FILEPATH = #{filepath,jdbcType=VARCHAR}
      ,FILENAME = #{filename,jdbcType=VARCHAR}
      ,TIME = #{time,jdbcType=TIMESTAMP}
      ,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
	  ,UPDATE_TIME = NOW()
      where 1=1
      and id = #{id,jdbcType=VARCHAR}

      update REP_REVEAL
      set 
      ANNEX_PATH = #{annexPath,jdbcType=VARCHAR}
      ,ANNEX = #{annex,jdbcType=VARCHAR}
      ,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
	  ,UPDATE_TIME = NOW()
      where 1=1
      and id = #{id,jdbcType=VARCHAR}

      update REP_REVEAL
      set 
      CONFIRM_STATUS = #{confirmStatus,jdbcType=VARCHAR},
      CONFIRM_DATE = #{confirmDate,jdbcType=DATE},
      CONFIRM_USER = #{confirmUser,jdbcType=VARCHAR}
      ,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
	  ,UPDATE_TIME = NOW()

	  	,IS_REVEAL=#{isReveal,jdbcType=VARCHAR}


	  	,IS_CONFIRM=#{isConfirm,jdbcType=VARCHAR}

      where 1=1
      and id = #{id,jdbcType=VARCHAR}

      update REP_REVEAL
      set 
      REVEAL_STATUS = #{revealStatus,jdbcType=VARCHAR},
      REVEAL_DATE = #{revealDate,jdbcType=DATE},
      REVEAL_USER = #{revealUser,jdbcType=VARCHAR}

	  	,IS_REVEAL=#{isReveal,jdbcType=VARCHAR}

      ,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
	  ,UPDATE_TIME = NOW()
      where 1=1
      and id = #{id,jdbcType=VARCHAR}

      update REP_REVEAL
      set 
      STATUS = #{status,jdbcType=VARCHAR}
      ,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
	  ,UPDATE_TIME = NOW()
      where 1=1
      and id = #{id,jdbcType=VARCHAR}

      update BOK_VALBAL_TABLE_STATUS a
      set confirm_Status=#{confirmStatusCode,jdbcType=VARCHAR}
      where 1=1

		and a.finprod_Id=#{finprodId,jdbcType=VARCHAR}


		and a.val_Date=STR_TO_DATE(#{valDate,jdbcType=VARCHAR},'%Y-%m-%d')


		and a.val_Bal_Flag=#{valBalFlagCode,jdbcType=VARCHAR}

      update BOK_VALBAL_TABLE_STATUS a
      set NOTICE_STATUS=#{noticeStatusCode,jdbcType=VARCHAR}
      where 1=1

		and a.finprod_Id=#{finprodId,jdbcType=VARCHAR}


		and a.val_Date=STR_TO_DATE(#{valDate,jdbcType=VARCHAR},'%Y-%m-%d')


		and a.val_Bal_Flag=#{valBalFlagCode,jdbcType=VARCHAR}

UPDATE REP_REVEAL
set CONFIRM_STATUS= #{confimStatus,jdbcType=VARCHAR}, IS_CONFIRM='01', IS_REVEAL='01', CONFIRM_DATE=null, CONFIRM_USER=null, UPDATE_USER=#{updateUser,jdbcType=VARCHAR}, UPDATE_TIME=NOW() WHERE 1=1 AND ID in
#{item}

update REP_REVEAL rr

	set rr.FILEPATH = null, rr.TIME = null, rr.FILENAME = null


	set rr.ANNEX = null, rr.ANNEX_PATH = null

,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
,UPDATE_TIME = NOW()
where rr.ID = #{id, jdbcType=VARCHAR}

      update REP_REVEAL
      set 
      FILEPATH = #{filepath,jdbcType=VARCHAR}
      ,FILENAME = #{filename,jdbcType=VARCHAR}
      ,TIME = #{time,jdbcType=DATE}
	  ,UPDATE_TIME = NOW()
      where 1=1
      and STATUS = 'E'

      and REPORT_NAME = #{reportName,jdbcType=VARCHAR}


      and PRODID = #{prodid,jdbcType=VARCHAR}


      and ( START_DATE = #{startDate,jdbcType=DATE}


		or END_DATE= #{startDate,jdbcType=DATE} )
